import numpy as np
class Transformation:
    """Invertible robust per-channel normalization (median/IQR) for forecasting inputs."""
    def fit(self, X, metadata):
        X = np.asarray(X, dtype=float)
        center = np.median(X, axis=0)
        q1, q3 = np.percentile(X, 25, axis=0), np.percentile(X, 75, axis=0)
        scale = np.where((q3 - q1) > 1e-8, (q3 - q1), 1.0)
        return {"center": center, "scale": scale}
    def transform(self, X, state):
        X = np.asarray(X, dtype=float)
        return (X - state["center"]) / state["scale"]
    def inverse_transform(self, Y, state):
        Y = np.asarray(Y, dtype=float)
        return Y * state["scale"] + state["center"]

import numpy as np
class Transformation:
    """Append causal rolling-mean channels (lag/rolling features) for forecasting."""
    def fit(self, X, metadata):
        return {"w": int(metadata.get("window", 8))}
    def transform(self, X, state):
        X = np.asarray(X, dtype=float); X = X.reshape(len(X), -1); w = state["w"]
        cs = np.cumsum(X, axis=0); roll = np.copy(X)
        if len(X) > w:
            roll[w:] = (cs[w:] - cs[:-w]) / w
        roll[:w] = cs[:w] / np.arange(1, min(w, len(X)) + 1)[:, None]
        return np.concatenate([X, roll], axis=1)

import numpy as np
class Transformation:
    """Robust residual + MAD z-score from a rolling-median baseline (anomaly features)."""
    def fit(self, X, metadata):
        return {"w": int(metadata.get("window", 16))}
    def transform(self, X, state):
        X = np.asarray(X, dtype=float).reshape(len(X), -1); w = state["w"]
        base = np.copy(X)
        for i in range(len(X)):
            base[i] = np.median(X[max(0, i - w + 1):i + 1], axis=0)
        resid = X - base
        mad = np.median(np.abs(resid - np.median(resid, axis=0)), axis=0) + 1e-8
        return resid / (1.4826 * mad)

import numpy as np
class Transformation:
    """Rolling local linear slope per channel (degradation / trend features)."""
    def fit(self, X, metadata):
        return {"w": int(metadata.get("window", 24))}
    def transform(self, X, state):
        X = np.asarray(X, dtype=float).reshape(len(X), -1); w = state["w"]; out = np.zeros_like(X)
        for i in range(len(X)):
            seg = X[max(0, i - w + 1):i + 1]; m = seg.shape[0]
            tt = np.arange(m) - (m - 1) / 2.0; d = (tt ** 2).sum() or 1.0
            out[i] = (tt[:, None] * seg).sum(axis=0) / d
        return out

import numpy as np
class Transformation:
    """Select the relevant sensor channels (e.g. PS1-PS6, FS1/FS2, VS1 from a pump scenario).
    Indices come from the scenario's relevant_sensors via metadata['channel_indices']."""
    def fit(self, X, metadata):
        return {"idx": list(metadata.get("channel_indices", []))}
    def transform(self, X, state):
        X = np.asarray(X, dtype=float).reshape(len(X), -1)
        idx = state["idx"] or list(range(X.shape[1]))
        return X[:, idx]

import numpy as np
class Transformation:
    """Aggregate normalized channels into a single condition/health index (decision support)."""
    def fit(self, X, metadata):
        X = np.asarray(X, dtype=float)
        return {"mean": X.mean(axis=0), "std": X.std(axis=0) + 1e-8,
                "w": np.asarray(metadata.get("weights", []), dtype=float)}
    def transform(self, X, state):
        X = np.asarray(X, dtype=float).reshape(len(X), -1)
        z = (X - state["mean"]) / state["std"]
        w = state["w"] if state["w"].size == z.shape[1] else np.ones(z.shape[1]) / z.shape[1]
        return (z * w).sum(axis=1, keepdims=True)
